        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook pasta in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra pecorino.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté garlic and ginger in oil.\n4. Add tomato sauce and spices, simmer 15 min.\n5. Stir in cream and cooked chicken.\n6. Simmer 10 more minutes. Serve with rice.", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles\nTofu\nBean sprouts\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nGarlic\nEggs", Steps = "1. Soak rice noodles in warm water 30 min.\n2. Make sauce: tamarind, fish sauce, sugar.\n3. Stir-fry tofu until golden.\n4. Scramble eggs in the pan.\n5. Add noodles and sauce, toss until coated.\n6. Top with peanuts, sprouts, and lime.", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco shells\nLettuce\nTomato\nCheddar cheese\nSour cream\nTaco seasoning", Steps = "1. Brown beef in skillet.\n2. Add taco seasoning and water, simmer 5 min.\n3. Warm taco shells in oven.\n4. Fill shells with beef.\n5. Top with lettuce, tomato, cheese, sour cream.\n6. Serve with salsa on the side.", AverageRating = 4.1, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt", Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Stir in diced onion, jalapeño, tomato.\n4. Add lime juice, cilantro, and salt.\n5. Taste and adjust seasoning.\n6. Serve immediately with chips.", AverageRating = 4.7, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Miso Ramen", Category = "Japanese", Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoy sauce\nSoft-boiled egg\nGreen onions\nCorn\nButter\nGarlic", Steps = "1. Bring broth to a simmer.\n2. Whisk in miso paste and soy sauce.\n3. Cook ramen noodles separately.\n4. Sauté garlic in butter.\n5. Assemble: noodles, broth, garlic butter.\n6. Top with egg, corn, and green onions.", AverageRating = 4.4, RatingCount = 11 },
        new Recipe { Id = 8, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Preheat oven to 425°F. Butter ramekins.\n2. Melt chocolate and butter together.\n3. Whisk in eggs, sugar, and vanilla.\n4. Fold in flour gently.\n5. Pour into ramekins, bake 12-14 min.\n6. Invert onto plates. Center should be molten.", AverageRating = 4.9, RatingCount = 25 },
    };

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}
